import type { AgentSpawnInput, EngineInterface, Register } from 'claude-code'

type Verdict = 'opus' | 'sonnet'

const words = (list: string) =>
  new RegExp(`\\b(?:${list.trim().split(/\s+/).join('|')})\\b`, 'i')

// When the judge can't answer: planning, audits and review stay on the main
// model ("opus only plans and audits"); everything else goes to Sonnet.
const KEEP = words(`
  plan plans planning planner audit audits auditing review reviews reviewing
  reviewer grade grades grading judge judging verify verifying verification
  critique critic architect architecture design designing decide evaluate
  evaluating evaluation score scoring rank ranking
`)

const JUDGE_SYSTEM = [
  "You route a coding agent's subagent to a model. Reply with exactly one word: opus or sonnet.",
  'opus: the task needs deep judgment where a mistake is costly: planning work or designing an ' +
    'architecture, deciding between approaches, auditing or reviewing for correctness or security, ' +
    'grading or evaluating other work, or debugging a subtle problem that spans many parts.',
  'sonnet: everything else: writing code, tests, content or data to a clear brief; searching, ' +
    'reading and summarizing; running commands and checks; mechanical edits, refactors and ' +
    'migrations with clear instructions.',
  'When unsure, sonnet.',
].join('\n')

// Asks Haiku whether the subagent needs Opus, from its task and the start of
// its instructions. Undefined when it can't say (an error, a time-out, the
// account's limit, a reply that is neither word).
async function judge($: EngineInterface, e: AgentSpawnInput): Promise<Verdict | undefined> {
  const reply = await $.model
    .complete({
      model: 'haiku',
      system: JUDGE_SYSTEM,
      prompt: `Subagent type: ${e.subagentType}\nTask: ${e.description}\n\nIts instructions, maybe cut:\n${e.prompt.slice(0, 4000)}`,
      maxTokens: 5,
      effort: 'low',
      timeoutMs: 10_000,
    })
    .catch(() => undefined)
  if (!reply?.isAnswered) return undefined
  const word = reply.text.trim().toLowerCase()

  return word.startsWith('opus') ? 'opus' : word.startsWith('sonnet') ? 'sonnet' : undefined
}

export const register: Register = on => {
  // Clears the agent count an earlier version pinned to the status line.
  on('session.start', ($, e, next) => {
    $.ui.status(undefined)

    return next(e)
  })

  on('agent.spawn', async ($, e, next) => {
    const asked = e.model ?? ''
    const runsOnOpus = /opus/i.test(asked) || (asked === '' && /opus/i.test(e.parentModel))
    // A fork shares the main conversation's cache, so it keeps its model; a
    // subagent not headed for Opus already costs less.
    if (e.fork || !runsOnOpus) return next(e)

    let verdict: Verdict
    let why: string
    if (e.subagentType === 'Explore') {
      verdict = 'sonnet'
      why = 'Explore only reads'
    } else {
      const ruled = await judge($, e)
      verdict = ruled ?? (KEEP.test(e.description) ? 'opus' : 'sonnet')
      why = ruled ? 'judge' : 'judge unavailable, by its words'
    }

    if (verdict === 'opus') {
      $.ui.log(`scout-router: "${e.description}" stays on Opus (${why})`)

      return next(e)
    }
    const ran = await next({ ...e, model: 'sonnet' })
    if (ran.deny === undefined) $.ui.log(`scout-router: "${e.description}" runs on ${ran.model} (${why})`)

    return ran
  })
}

